contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(from != address(this));
        Reverter reverter = new Reverter();
        address[] memory tos = new address[](1);
        tos[0] = address(reverter);
        bool referenceReverted = false;
        try c.transfer(from, address(reverter), tos, v) returns (bool res) {
        } catch {
            referenceReverted = true;
        }
        assertTrue(referenceReverted, "Reference should revert when external call fails");
    }
}

contract Reverter {
    fallback() external payable {
        revert("transferFrom failed");
    }
